// Crawl plan. Two sites, chosen because they are server-rendered (no headless
// browser needed) and cover both an aggregator and a lender's own page:
//   1. BankBazaar - one rate-comparison table (many lenders at once) plus
//      per-lender pages that carry the eligibility criteria.
//   2. ICICI Bank  - the lender's official eligibility page; official values
//      take precedence over the aggregator when both are present.
const BB = 'https://www.bankbazaar.com';

const targets = [
  { kind: 'rate_table', source: 'bankbazaar', url: `${BB}/personal-loan-interest-rate.html` },
  { kind: 'lender_page', source: 'bankbazaar', lender: 'HDFC Bank', url: `${BB}/hdfc-personal-loan.html` },
  { kind: 'lender_page', source: 'bankbazaar', lender: 'State Bank of India', url: `${BB}/sbi-personal-loan.html` },
  { kind: 'lender_page', source: 'bankbazaar', lender: 'ICICI Bank', url: `${BB}/icici-personal-loan.html` },
  { kind: 'lender_page', source: 'bankbazaar', lender: 'Kotak Mahindra Bank', url: `${BB}/kotak-personal-loan.html` },
  { kind: 'lender_page', source: 'bankbazaar', lender: 'Bajaj Finserv', url: `${BB}/bajaj-finserv-personal-loan.html` },
  { kind: 'lender_page', source: 'official', lender: 'ICICI Bank',
    url: 'https://www.icicibank.com/personal-banking/loans/personal-loan/eligibility' },
];

return targets.map(t => ({ json: t }));

// Turns raw HTML into (a) rate-table rows and (b) a compact eligibility
// snippet per lender page, plus cheap regex "heuristic" extraction.
//
// Cost trick #1: the LLM never sees a full page. We keep only ~3 KB of text
// around eligibility keywords (pages are 200 KB - 1.2 MB of HTML), which cuts
// tokens by ~98% and also improves extraction accuracy (less noise).
// Cost trick #2: a content hash of that snippet lets the next node skip the
// LLM entirely when the page has not changed since the last crawl.

const targets = $('Crawl targets').all().map(i => i.json);
const pages = $input.all();

// ---------------------------------------------------------------- helpers
const ENTITIES = { '&amp;': '&', '&nbsp;': ' ', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&#8377;': '₹', '&rsquo;': "'", '&ndash;': '-', '&mdash;': '-' };
const decode = s => s.replace(/&[#a-z0-9]+;/gi, m => ENTITIES[m.toLowerCase()] ?? ' ');

function htmlToText(html) {
  return decode(
    html.replace(/<(script|style|noscript|svg|header|footer|nav)[\s\S]*?<\/\1>/gi, ' ')
        .replace(/<[^>]+>/g, ' ')
  ).replace(/\s+/g, ' ').trim();
}

// cyrb53: fast 53-bit string hash - plenty for change detection, no crypto module needed.
function hash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

const num = s => Number(String(s).replace(/,/g, ''));

function parseRates(text) {
  // first "a% - b%" range that looks like an interest rate (skips fee ranges such as "0% - 6%")
  for (const m of text.matchAll(/(\d{1,2}(?:\.\d{1,2})?)\s*%(?:\s*p\.a\.?)?\s*(?:to|-|–)\s*(\d{1,2}(?:\.\d{1,2})?)\s*%/gi)) {
    const lo = num(m[1]), hi = num(m[2]);
    if (lo >= 5 && hi <= 45 && hi >= lo) return { interest_rate_min: lo, interest_rate_max: hi };
  }
  const single = text.match(/(\d{1,2}(?:\.\d{1,2})?)\s*%\s*p\.a\./i);
  return single && num(single[1]) >= 5 ? { interest_rate_min: num(single[1]), interest_rate_max: null } : {};
}

function parseRateTable(html) {
  const tables = html.match(/<table[\s\S]*?<\/table>/gi) || [];
  for (const table of tables) {
    const rows = (table.match(/<tr[\s\S]*?<\/tr>/gi) || []).map(r =>
      (r.match(/<t[dh][\s\S]*?<\/t[dh]>/gi) || []).map(c => htmlToText(c)));
    if (!rows.length || !/interest/i.test(rows[0].join(' '))) continue;
    return rows.slice(1)
      .filter(r => r.length >= 2 && r[0] && /\d/.test(r[1]))
      .map(r => ({ lender: r[0], processing_fee: r[2] || null, ...parseRates(r[1]) }));
  }
  return [];
}

const KEYWORDS = /eligib|minimum (net )?(monthly )?(income|salary)|credit score|cibil|age (limit|criteria|of)|years of age|salaried|self[- ]employed|work experience|loan amount/gi;

// Facts look like "Rs. 25,000", "750", "21 years", "10.5%": windows dense in them are
// eligibility tables; windows without them are navigation menus or marketing copy.
const FACT = /(?:rs\.?|₹|inr)\s*[\d,]{4,}|\b[3-9]\d{2}\b|\b\d{2}\s*years|\d%/gi;

function eligibilitySnippet(text, maxLen = 3500) {
  const windows = [];
  for (const m of text.matchAll(KEYWORDS)) {
    const start = Math.max(0, m.index - 200), end = Math.min(text.length, m.index + 300);
    const last = windows[windows.length - 1];
    if (last && start <= last.end) last.end = end; else windows.push({ start, end });
  }
  // keep the most fact-dense windows that fit the budget, then restore page order
  const ranked = windows
    .map(w => ({ ...w, facts: (text.slice(w.start, w.end).match(FACT) || []).length }))
    .filter(w => w.facts > 0)
    .sort((a, b) => b.facts / (b.end - b.start) - a.facts / (a.end - a.start));
  const picked = [];
  let used = 0;
  for (const w of ranked) {
    const len = Math.min(w.end - w.start, 800);
    if (used + len > maxLen) continue;
    picked.push({ start: w.start, end: w.start + len });
    used += len;
  }
  return picked.sort((a, b) => a.start - b.start).map(w => text.slice(w.start, w.end)).join(' … ');
}

// Regex fallback, run over the whole page text (cheap) - used when no LLM is
// configured and to pre-fill fields the LLM leaves empty.
function heuristics(text, html) {
  const h = {};
  const incomes = [...text.matchAll(/minimum[^.]{0,30}?(?:monthly\s+)?(?:income|salary|nmi)[^₹\d]{0,40}?(?:rs\.?|₹|inr)\s*([\d,]{4,9})/gi)]
    .map(m => num(m[1])).filter(v => v >= 5000 && v <= 500000);
  // some lender pages embed their eligibility calculator config, e.g. "minIncome":30000
  const calc = html.match(/minIncome["']?\s*:\s*["']?(\d{4,7})/);
  if (calc) incomes.push(num(calc[1]));
  if (incomes.length) h.min_monthly_income = Math.min(...incomes);

  const cs = text.match(/(?:credit|cibil)\s+score\s+(?:of\s+|over\s+|above\s+|at least\s+|minimum\s+)?([5-8]\d{2})\b/i);
  if (cs) h.min_credit_score = num(cs[1]);

  const age = text.match(/age\s+(?:at least|between|of|from)?\s*(\d{2})\s*(?:years)?\s*(?:and|to|-)\s*(?:less than|up to|upto|below)?\s*(\d{2})/i)
           || text.match(/(\d{2})\s*(?:years)?\s*(?:to|-|–)\s*(\d{2})\s*years/i);
  if (age && num(age[1]) >= 18 && num(age[2]) <= 80 && num(age[1]) < num(age[2])) {
    h.min_age = num(age[1]); h.max_age = num(age[2]);
  }
  if (/(?:must be|should be|only)\s+salaried|salaried (?:indian )?residents/i.test(text)) h.employment_types = ['salaried'];

  const amt = text.match(/up to\s*(?:rs\.?|₹)\s*([\d.]+)\s*(lakh|crore|l\b)/i);
  if (amt) h.max_loan_amount = num(amt[1]) * (/crore/i.test(amt[2]) ? 1e7 : 1e5);
  Object.assign(h, parseRates(text));
  return h;
}

// ---------------------------------------------------------------- main
const out = [];
pages.forEach((page, idx) => {
  const t = targets[idx];
  const html = page.json.html;
  if (!html || page.json.error) {
    out.push({ json: { ...t, ok: false, error: String(page.json.error?.message || page.json.error || 'empty response') } });
    return;
  }
  if (t.kind === 'rate_table') {
    out.push({ json: { ...t, ok: true, rates: parseRateTable(html) } });
    return;
  }
  const text = htmlToText(html);
  const snippet = eligibilitySnippet(text);
  out.push({ json: { ...t, ok: snippet.length > 0, snippet, content_hash: hash(snippet), heuristic: heuristics(text, html) } });
});
return out;

// Decide which lender pages actually need the LLM.
// A page is sent only if (a) its snippet hash changed since the last crawl and
// (b) an LLM key is configured. Otherwise we reuse the cached extraction or
// fall back to the regex heuristics. Always emits >= 1 item so the IF node
// downstream runs (n8n stops a branch that receives zero items).

const pages = $('Clean, parse & fingerprint').all().map(i => i.json);
const cache = new Map($input.all().filter(i => i.json.url).map(i => [i.json.url, i.json]));
const llmEnabled = Boolean($env.LLM_API_KEY);

const SYSTEM = `You extract personal-loan eligibility criteria from Indian bank web page text.
Return ONLY a JSON object with these keys (use null when the text does not state it):
{"product_name": string, "interest_rate_min": number, "interest_rate_max": number,
 "min_monthly_income": number (INR per month), "min_credit_score": number,
 "min_age": number, "max_age": number,
 "employment_types": array of "salaried" | "self_employed" | "business" (null if not restricted),
 "max_loan_amount": number (INR), "other_criteria": string (<= 200 chars, qualitative rules
 such as work experience or employer type)}.
If different minimum incomes are given for different cities or employment types, use the LOWEST.`;

const work = pages
  .filter(p => p.kind === 'lender_page' && p.ok)
  .filter(p => cache.get(p.url)?.content_hash !== p.content_hash)
  .filter(() => llmEnabled)
  .map(p => ({
    json: {
      url: p.url,
      llm_request: {
        model: $env.LLM_MODEL || 'gemini-3.5-flash-lite',
        temperature: 0,
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: `Lender: ${p.lender}\nPage text:\n${p.snippet}` },
        ],
      },
    },
  }));

return work.length ? work : [{ json: { skip: true, reason: llmEnabled ? 'all pages unchanged' : 'LLM disabled' } }];

// Parse the LLM's JSON answers (one per lender page). Items line up 1:1 with
// the "Plan LLM extraction" items. Bad / failed responses become null and the
// finaliser falls back to cache or heuristics for that page.
const requests = $('Plan LLM extraction').all().map(i => i.json);

function firstJsonObject(text) {
  const m = String(text || '').match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch { return null; }
}

return $input.all().map((item, idx) => {
  const content = item.json.choices?.[0]?.message?.content;
  const extracted = firstJsonObject(content);
  return { json: { url: requests[idx].url, extracted, error: extracted ? null : (item.json.error?.message || 'unparseable LLM response') } };
});

// Merge every source into one row per lender and hand a single JSON payload to
// Postgres (one bulk upsert instead of one query per product).
//
// Field precedence per lender:  official site > aggregator page
//                    per page:  fresh LLM > cached extraction > regex heuristic
// Anything still missing gets conservative industry defaults, flagged as
// criteria_source = 'default' so the matcher can down-weight it.

const pages = $('Clean, parse & fingerprint').all().map(i => i.json);
const cache = new Map($('Load crawl cache').all().filter(i => i.json.url).map(i => [i.json.url, i.json]));
let fresh = new Map();
try {
  fresh = new Map($('Parse LLM output').all().filter(i => i.json.extracted).map(i => [i.json.url, i.json.extracted]));
} catch (e) { /* LLM branch did not run this time */ }

const DEFAULTS = { min_monthly_income: 25000, min_credit_score: 750, min_age: 21, max_age: 60 };
const FIELDS = ['interest_rate_min', 'interest_rate_max', 'min_monthly_income', 'min_credit_score', 'min_age',
  'max_age', 'employment_types', 'max_loan_amount', 'other_criteria', 'product_name'];
const EMP = new Set(['salaried', 'self_employed', 'business']);

const slug = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const canonicalLender = name => name.replace(/\s+(personal loan|ltd\.?|limited)$/i, '').trim();
const isNum = v => typeof v === 'number' && Number.isFinite(v);

function clean(e = {}) {
  const out = {};
  for (const f of FIELDS) {
    const v = e[f];
    if (v === null || v === undefined || v === '') continue;
    if (f === 'employment_types') {
      const list = (Array.isArray(v) ? v : []).map(x => String(x).toLowerCase().replace(/[- ]/g, '_')).filter(x => EMP.has(x));
      if (list.length) out[f] = [...new Set(list)];
    } else if (f === 'other_criteria' || f === 'product_name') {
      out[f] = String(v).slice(0, 300);
    } else if (isNum(Number(v))) {
      out[f] = Number(v);
    }
  }
  // sanity bounds - an LLM or regex misread must not produce absurd criteria
  const outside = (f, lo, hi) => out[f] !== undefined && (out[f] < lo || out[f] > hi);
  if (outside('min_credit_score', 300, 900)) delete out.min_credit_score;
  if (outside('min_monthly_income', 1000, 1000000)) delete out.min_monthly_income;
  if (outside('interest_rate_min', 5, 45)) delete out.interest_rate_min;
  if (outside('interest_rate_max', 5, 45) || out.interest_rate_max < out.interest_rate_min) delete out.interest_rate_max;
  if (outside('min_age', 18, 70) || outside('max_age', 21, 80)) { delete out.min_age; delete out.max_age; }
  return out;
}

// --- 1. per-page extraction, choosing the best available source -------------
const lenders = new Map(); // lender -> { official: {...}, aggregator: {...}, urls, sources }
const cacheRows = [];
for (const p of pages.filter(p => p.kind === 'lender_page' && p.ok)) {
  let extracted, via;
  if (fresh.has(p.url)) { extracted = fresh.get(p.url); via = 'llm'; }
  else if (cache.get(p.url)?.content_hash === p.content_hash && cache.get(p.url)?.extracted) {
    extracted = cache.get(p.url).extracted; via = cache.get(p.url).extracted._via || 'llm';
  } else { extracted = p.heuristic; via = 'heuristic'; }

  const record = { ...clean(p.heuristic), ...clean(extracted) }; // LLM/cached values override regex
  // Only cache LLM results: a heuristic-only page must be retried once an LLM key is available.
  if (via === 'llm') cacheRows.push({ url: p.url, content_hash: p.content_hash, extracted: { ...record, _via: via } });

  const key = canonicalLender(p.lender);
  const entry = lenders.get(key) || { lender: key, official: null, aggregator: null, url: p.url, via: new Set() };
  entry[p.source === 'official' ? 'official' : 'aggregator'] = record;
  if (p.source === 'official') entry.url = p.url;
  entry.via.add(via);
  lenders.set(key, entry);
}

// --- 2. add rate-table lenders (rates + fees for many lenders in one page) ---
const rateRows = pages.find(p => p.kind === 'rate_table' && p.ok)?.rates || [];
const rateUrl = pages.find(p => p.kind === 'rate_table')?.url;
for (const r of rateRows) {
  const key = canonicalLender(r.lender);
  const entry = lenders.get(key) || { lender: key, official: null, aggregator: null, url: rateUrl, via: new Set(['default']) };
  entry.table = r;
  lenders.set(key, entry);
}

// --- 3. merge into product rows ---------------------------------------------
const products = [];
for (const e of lenders.values()) {
  const merged = { ...(e.table ? clean(e.table) : {}), ...(e.aggregator || {}), ...(e.official || {}) };
  const usedDefaults = Object.keys(DEFAULTS).filter(k => merged[k] === undefined);
  for (const k of usedDefaults) merged[k] = DEFAULTS[k];
  const criteriaSource = usedDefaults.length === Object.keys(DEFAULTS).length ? 'default'
    : e.via.has('llm') ? 'llm' : 'heuristic';
  products.push({
    product_key: `${slug(e.lender)}-personal-loan`,
    lender: e.lender,
    product_name: merged.product_name || `${e.lender} Personal Loan`,
    interest_rate_min: merged.interest_rate_min ?? null,
    interest_rate_max: merged.interest_rate_max ?? null,
    processing_fee: e.table?.processing_fee ?? null,
    min_monthly_income: merged.min_monthly_income,
    min_credit_score: merged.min_credit_score,
    max_credit_score: null,
    min_age: merged.min_age,
    max_age: merged.max_age,
    employment_types: merged.employment_types ?? null,
    max_loan_amount: merged.max_loan_amount ?? null,
    other_criteria: merged.other_criteria ?? null,
    source_url: e.url,
    criteria_source: criteriaSource,
  });
}

const summary = {
  pages_ok: pages.filter(p => p.ok).length,
  pages_failed: pages.filter(p => !p.ok).map(p => p.url),
  llm_extractions: fresh.size,
  products: products.length,
  by_criteria_source: products.reduce((a, p) => ({ ...a, [p.criteria_source]: (a[p.criteria_source] || 0) + 1 }), {}),
};
if (!products.length) throw new Error(`Crawl produced no products: ${JSON.stringify(summary)}`);

return [{ json: { products_json: JSON.stringify(products), cache_json: JSON.stringify(cacheRows), summary } }];
